72	export function totalPaidCents(callback) {
73	  query('orders', (o) => o.status === 'paid' && o.deleted_at === null, (err, rows) => {
74	    if (err) return callback(err);
75	    callback(null, rows.reduce((sum, o) => sum + o.total_cents, 0));
76	  });
